mapper.update:

        /*updateSelectedDataDiReg_1*/
			UPDATE DB_OFF_IV A	
			   SET A.DI_DATE=#{st_di_date},	
			   	   A.DI_QTY=NVL(A.DI_QTY,0)+${st_di_qty}	
			 WHERE A.BUYER=#{st_buyer}	
			   AND A.ADD_DATE=#{st_add_date}	
			   AND A.SEQ=${st_seq}		
			   AND A.DS_SEQ=${st_ds_seq}


        /*updateSelectedDataDiReg_2*/
			UPDATE DB_OFF_PO A	
			   SET A.DI_QTY=NVL(A.DI_QTY,0)+${st_di_qty}	
			 WHERE A.BUYER=#{st_buyer}	
			   AND A.ADD_DATE=#{st_add_date}	
			   AND A.SEQ=${st_seq}


        /*updateSelectedDataDiCancelReg_1*/
			UPDATE DB_OFF_IV A	
			   SET A.DI_DATE=NULL,	
			   	   A.DI_QTY=NVL(A.DI_QTY,0)-${st_di_qty}	
			 WHERE A.BUYER=#{st_buyer}	
			   AND A.ADD_DATE=#{st_add_date}	
			   AND A.SEQ=${st_seq}		
			   AND A.DS_SEQ=${st_ds_seq}


        /*updateSelectedDataDiCancelReg_2*/
			UPDATE DB_OFF_PO A	
			   SET A.DI_QTY=NVL(A.DI_QTY,0)-${st_di_qty}	
			 WHERE A.BUYER=#{st_buyer}	
			   AND A.ADD_DATE=#{st_add_date}	
			   AND A.SEQ=${st_seq}


        /*updateSelectedDataIvCancelReg_1*/
			UPDATE DB_OFF_IV A		
			   SET A.INV_DATE=NULL,	
			 	   A.INV_USER_ID=NULL,	
			 	   A.INV_ADD_DATE=TO_CHAR(SYSDATE,'YYYYMMDD'),	
			 	   A.INV_ADD_TIME=TO_CHAR(SYSDATE,'HH24MISS')	
			 WHERE A.BUYER=#{st_buyer}	
			   AND A.ADD_DATE=#{st_add_date}	
			   AND A.SEQ=${st_seq}		
			   AND A.DS_SEQ=${st_ds_seq}


        /*updateSelectedDataIvCancelReg_2*/
			UPDATE DB_OFF_PO A					
			   SET A.IV_QTY=NVL(A.IV_QTY,0)-${st_ds_qty}	
			 WHERE A.BUYER=#{st_buyer}					
			   AND A.ADD_DATE=#{st_add_date}					
			   AND A.SEQ=${st_seq}
